-- Platsbeskrivningar, omgång 1 (40 platser). Skrivna utifrån platsernas egna hemsidor.
-- Kort text högst 7 ord, lång 70–100 ord.
begin;
update public.places set short_description = 'Gårdshotell med spa, restaurang och konferens', description = 'Örums Nygård är en generationsgård mellan Ystad och Simrishamn som sedan 2003 tar emot gäster. Här finns 21 personligt inredda hotellrum, ett spa och en restaurang som lagar mat på råvaror från trakten. Gården har också lokaler för konferens, fest och bröllop. Familjen har byggt upp verksamheten steg för steg, från ett gammalt grisstall till dagens hotell, och lägger stor vikt vid personligt värdskap och hållbara val. Hit kommer man för en helg, en middag eller ett möte i lantlig miljö.' where id = 1; -- Örums Nygård Gårdshotell Spa & Konferens
update public.places set short_description = 'Familjeägt musteri i Kivik sedan 1888', description = 'Kiviks Musteri är ett familjeföretag som funnits i Kivik sedan 1888, då de första äppelträden planterades. Musteriet ligger mellan Hanöbukten, Stenshuvuds nationalpark och de egna äppelodlingarna. Här görs muster, cider och andra äppelprodukter med fem generationers hantverk bakom sig. På plats finns en butik, Bistro Kärnhuset med smakpaket och kurser som beskärning och ympning. Odlingarna sköts med fokus på biologisk mångfald, och i nyttodjursparkerna kan stora och små lära sig om insekternas roll. Musteriet har även en webbshop och erbjuder konferens.' where id = 2; -- Kiviks Musteri
update public.places set short_description = 'Bageri, konditori och café på gammal gård', description = 'Olof Viktors ligger på en fyrlängad gård från 1890 i Glemminge och har varit bageri, konditori och café sedan 2002. Bagarna bakar allt för hand och från grunden, och brödet gräddas i en vedeldad stenugn. I butiken kan man köpa med sig bröd och bakverk, och caféet har både sittplatser inomhus och en stenlagd gårdsplan. Olof Viktors har listats som ett av landets bästa caféer. Hit kommer många för en fika eller för att handla bröd på vägen genom Österlen.' where id = 3; -- Olof Viktors i Glemmingebro
update public.places set short_description = 'Släktgård med egen kallpressad rapsolja', description = 'Gunnarshögs Gård har tillhört familjen Nilsson sedan 1897 och har gått från traditionellt jordbruk till att göra kallpressad rapsolja, från frö till flaska. I gårdsbutiken finns rapsoljor i flera smaker, till exempel med örter, chili och vitlök eller kallrökt, och sortimentet finns även i en nätbutik. Under sommaren och vid vissa helger håller en liten gårdskiosk öppet på innergården. Gården delar gärna med sig av kunskap om raps och om var bra mat kommer ifrån, och på hemsidan finns recept med rapsolja.' where id = 4; -- Gunnarshögs Gård
update public.places set short_description = 'Nordens bäst bevarade medeltida borg', description = 'Glimmingehus är Nordens bäst bevarade medeltida borg. Grundstenen lades den 2 maj 1499 av den danske riddaren Jens Holgersen Ulfstand, en av Danmarks mäktigaste män på sin tid. Borgen står kvar mitt på Österlenslätten och går att besöka under öppettiderna. Här ordnas visningar, verkstäder, föreläsningar och evenemang under året, till exempel medeltida lucia och S:t Nikolai afton. För skolklasser finns kostnadsfria program. Glimmingehus är ett bra utflyktsmål för den som är nyfiken på medeltiden och Österlens historia.' where id = 6; -- Glimmingehus
update public.places set short_description = 'Hotell och krog i Simrishamns hamn', description = 'Maritim Hotell & Krog ligger i hamnen i Simrishamn, med Storgatans butiker, kaféer och gallerier ett stenkast bort. Hotellet har ljusa, personligt inredda rum med fritt wifi, och flera rum har utsikt över hamnen. Det finns även hundvänliga rum. Frukost serveras varje morgon, och under sommaren kan man äta den på uteserveringen med utsikt över vattnet. Krogen serverar mat och dryck i en ombonad miljö, och hotellet erbjuder paket med övernattning och trerättersmiddag. Hotellet har öppet året runt.' where id = 8; -- En gaffel kort på Maritim
update public.places set short_description = 'Fisk, skaldjur och restauranger i Kivik', description = 'Buhres ligger precis vid havet i Kivik och startades 1984 av familjen Buhre, då som en plats där man sålde färsk fisk till byborna. I dag finns här både restauranger och en fisk- och delikatessbutik med färsk fisk, skaldjur och produkter från det egna rökeriet. Sortimentet följer säsongen och finns även i en onlinebutik. Maten lagas på färska råvaror med ett modernt sätt att laga mat, men med respekt för traditionellt hantverk och regionens matkultur. Buhres är en mötesplats för dem som gillar mat från havet.' where id = 10; -- Buhres i Kivik
update public.places set short_description = 'Pizzahantverk i Gladsax', description = 'Gustafs på Österlen är en pizzeria i Gladsax som jobbar med pizzahantverk. Förutom restaurangen gör Gustafs egen fryst pizza som säljs i butiker runt om i Sverige, och handlare kan beställa den direkt. Restaurangen ordnar också egna evenemang, till exempel ett pizzabord till jul i stället för det klassiska julbordet. Bakom Gustafs står ett litet team som vill driva verksamheten med ärlighet, nyfikenhet och generositet. Öppettiderna varierar över året, så det är bäst att titta på deras hemsida innan man åker dit.' where id = 11; -- Gustafs På Österlen
update public.places set short_description = 'Daniel Berlins restaurang och boutiquehotell', description = 'Vyn är kocken Daniel Berlins restaurang och boutiquehotell utanför Skillinge. Restaurangen lagar säsongsbetonad mat med rötter i det skånska och skandinaviska köket och i den lokala floran och faunan. Här finns även en mer avslappnad mat- och vinbar med lättare rätter, och Ateljén, ett avskilt rum för privata middagar för 2 till 24 gäster. Boutiquehotellet har 15 rum för den som vill stanna över natten, och det finns paket som kombinerar middag och boende. Bordet bokas i förväg via deras hemsida.' where id = 12; -- Vyn Resturant
update public.places set short_description = 'Gästgiveri i Hammenhög sedan 1693', description = 'Hammenhögs Gästgivaregård har tagit emot resenärer i över 300 år, sedan 1693. Sedan 2022 drivs gästgiveriet av Ellen och Shaun Thompson, som båda har lång erfarenhet av restaurang och hotell. Här serveras dagens lunch under stora delar av året, och på sommaren middag både i matsalen och i den grönskande trädgården. På fredagar är det pub och kvällsservering i stort sett året runt. Gästgiveriet har också mysiga rum och frukost, och ordnar quizkvällar, konserter, högtider, fester och bröllop.' where id = 13; -- Hammenhögs Gästgivaregård
update public.places set short_description = 'Antik, möbler och vintage utanför Smedstorp', description = 'Mrs Walker Antik & Design är en butik utanför Smedstorp som drivs av systrarna Meta och Cecilia Pusch. Här finns äldre möbler, porslin, glas, keramik, textilier och kuriosa, allt med en historia. Systrarna lagar, rengör, målar och återställer det mesta så att det blir bruksfärdigt igen, och de renoverar möbler och syr. Tanken är att fint gammalt hantverk ska få leva vidare i generationer. Butiken har begränsade öppettider, ofta bara lördagar, så det är bra att kolla hemsidan eller ringa innan besöket.' where id = 14; -- Mrs Walker antik & design
update public.places set short_description = 'Hotell och restaurang i Brösarps backar', description = 'Talldungen ligger mitt i Brösarps backar, omgiven av tallar, i två sammanbyggda stenhus från början av 1930-talet. Husen byggdes som traktens första vårdhem. Familjen som driver Talldungen i dag kom hit med en dröm om att skapa en plats för det goda livet på landet. Här finns ett hotell och en restaurang med fokus på god mat, vin och möten mellan människor, med den kuperade naturen runt omkring. Man kan boka bord eller kombinera middag med övernattning via deras hemsida.' where id = 16; -- Talldungens gårdshotell
update public.places set short_description = 'Gårdshotell med spa i Kåseberga', description = 'Kåseberga Gårdshotell & Spa är ett gårdshotell i Kåseberga, en liten by vid havet på södra Österlen. Hotellet erbjuder boende och spa i lugn miljö, nära både kusten och Ales stenar. Det är en plats för den som vill varva ner och ta det lugnt en tid på Österlen. Hotellet har periodvis varit stängt för renovering, så kolla deras hemsida för aktuell information om öppettider och bokning innan besöket. Frågor kan skickas via kontaktformuläret, och hotellet lovar att svara inom ett dygn.' where id = 17; -- Kåseberga Gårdshotell & Spa
update public.places set short_description = 'Golfklubb med två banor vid havet', description = 'Österlens Golfklubb bildades 1945 och ligger vid Viks fiskeläge, där havet möter land. Klubben har två 18-hålsbanor med helt olika karaktär på var sin sida om landsvägen: Lilla Vik, en lummig parkbana där flera hål går längs Östersjöns strandbrink och bland äppelträd, och Djupadal, en hedlandsbana. Det finns även Korta Vik, en korthålsbana med sex hål som man kan spela utan medlemskap. Klubben har proshop, restauranger, golflektioner och padel, och man kan boka starttid och boende via hemsidan.' where id = 18; -- Österlens Golfklubb - Lilla Vik
update public.places set short_description = 'Lägenheter och outdoorbutik i Kåseberga', description = 'Kåseberga HideOut är både uthyrning och butik i Kåseberga. Här finns genomtänkt inredda lägenheter för upp till fem personer, som går att hyra hela året. I butiken säljs friluftsutrustning och kvalitetsprodukter för livet utomhus, och den håller öppet från påsk. Bakom HideOut står Ulf Skarin, som också berättar om sitt liv med campervan på hemsidan. Kåseberga ligger vid havet på södra Österlen, nära Ales stenar, så lägenheterna passar bra som bas för den som vill vandra, bada eller utforska kusten.' where id = 20; -- Kåseberga Hideout
update public.places set short_description = 'Gårdshotell med restaurang nära Kivik', description = 'Blåsingsborg Gårdshotell är ett litet, personligt hotell på landet nära Kivik och Simrishamn. Hotellet har 20 personligt inredda rum, frukost och gårdspaket för den som vill stanna lite längre. I gårdsrestaurangen serveras en säsongsbetonad trerättersmeny på närproducerade råvaror, vanligtvis på fredag- och lördagkvällar. Gården tar också emot konferenser och företagsevent i lantlig miljö. Hundar är välkomna. Hotellet passar för en romantisk helg, en lugn semester på Österlen eller ett möte nära havet och naturen.' where id = 21; -- Blåsingsborg Gårdshotell
update public.places set short_description = 'Café, butik och växthus i Kåseberga', description = 'Backagården ligger i Kåseberga och vill fånga känslan av att Österlen möter Medelhavet. I växthuset kan man fika under vindruvsrankorna, och caféet serverar mackor, sallad, hemmagjord paj och varmrätter som skeppargryta. I butiken finns kläder, utvalda presentartiklar och Backagårdens egna produkter. Växthuset och orangeriet hyrs också ut för bröllop och fester. Backagården är ett ställe att stanna till på för en fika eller lunch när man besöker Kåseberga och kusten.' where id = 22; -- Backagården Café, Vin & Bistro på Österlen
update public.places set short_description = 'Anrikt café vid Stenshuvud sedan 1956', description = 'Kaffestugan Annorlunda öppnade 1956 och ligger vid Stenshuvuds nationalpark nära Kivik. Spetsdukarna ligger kvar på borden precis som förr, men här finns också cappuccino och mackor med handskalade räkor. Caféet bakar själv sina kakor till kakbuffén, åtta sorter, och sina surdegspizzor från grunden i det egna bageriet, med mjöl från Sveriges äldsta kvarn. Man kan sitta i den stora salen eller i den lummiga trädgården. Sedan 2015 drivs Kaffestugan av Catharina och Johan, som håller historien levande.' where id = 23; -- Kaffestugan Annorlunda
update public.places set short_description = 'Gårdskrog med vedugnspizza i Simrishamn', description = 'Gårdens vedugn är en liten gårdskrog i Simrishamn där man sitter bland blåregn och olivträd. Köket är italienskt men lagar maten på österlenska råvaror, och specialiteten är pizzor bakade i vedugn. Det finns även vin, drinkar och avec. Restaurangen har säsongsöppet och håller stängt under vintern, så det är bäst att kolla deras hemsida innan man åker dit. Bord kan bokas via hemsidan. Gårdens passar bra för en kväll med god mat i en lugn trädgårdsmiljö.' where id = 24; -- Gårdens Vedugn
update public.places set short_description = 'Gårdsbutik med frukt och grönt', description = 'Gröna Butiken är gårdsbutiken på Orelund, en fruktodlingsgård mellan Simrishamn och Kivik, strax norr om Vik. På gården odlas äpple, päron, plommon och körsbär, jordgubbar och hallon, och i växthuset ett tjugotal sorters tomater samt gurka, paprika och chili. I butiken säljs gårdens egna produkter och varor från andra lokala producenter. Under vinterhalvåret finns en självbetjäningsbod med äpplen, must och cider. Sedan 2020 drivs Orelund av systrarna Madeleine och Alexandra Nilsson. Öppettiderna varierar under lågsäsong.' where id = 26; -- Gröna Butiken på Orelund
update public.places set short_description = 'Gårdshotell, restaurang och gårdsbutik i Brösarp', description = 'Farmors Lycka är ett gårdshotell med restaurang och gårdsbutik, med utsikt över Östersjön och naturen runt omkring. Huset stod tomt i trettiofem år efter att farmor flyttat in till byn, tills det fick nytt liv. Här kan man bo i stillsam miljö och välja mellan olika hotellpaket. I restaurangen serveras gårdsmenyer på kvällarna, och här ordnas matevenemang under året. I gårdsbutiken finns dagsfärska ägg, egen kallpressad rapsolja och kött från gårdens grisar och lamm.' where id = 28; -- Farmors Lycka
update public.places set short_description = 'Golf, hotell och padel i Tomelilla', description = 'Tomelilla Golf är en anläggning med en 18-hålsbana och en niohåls pay and play-bana. Här finns också ett hotell med 32 bäddar, en restaurang, footgolf och en golfshop. I inomhushallen finns två padelbanor, bowls och simulatorgolf med Trackman i två bås. Klubben har ingen kö, och man behöver varken betala inträdesavgift eller spelrätt för att bli medlem. Det finns flera medlemsformer att välja mellan. På hemsidan kan man boka starttid, boende och golfpaket och läsa om aktuell banstatus.' where id = 32; -- Tomelilla Golf AB
update public.places set short_description = 'Dressincykling på gammal järnväg vid Gyllebo', description = 'Dressin på Österlen låter dig cykla dressin på en gammal järnvägsbana mellan Sankt Olof och Gyllebo. Verksamheten startades av Stephan, som 1985 blev ägare till en gammal cykeldressin tillsammans med sin far, och dressincyklingen i Sankt Olof har funnits sedan 1997. Turen går genom natur och landskap, och den kan kombineras med en tur med ångtåget mellan Sankt Olof och Brösarp. Det finns även program för skolor. Bokning, säkerhetsregler och vägbeskrivning finns på hemsidan.' where id = 33; -- Dressin på Österlen - Gyllebosjö
update public.places set short_description = 'Dressincykling på gammal järnväg i Fyledalen', description = 'Dressin på Österlen låter dig cykla dressin på en gammal järnvägsbana mellan Tomelilla och Fyledalen. Här startade allt i augusti 1989, när Stephan och hans far Helge började med dressincykling i Tomelilla. Turen går ut mot Fyledalen, en dalgång med rik natur och fina vandringsmöjligheter. Dressincyklingen passar både familjer och grupper, och det finns även program för skolor. På hemsidan finns bokning, säkerhetsregler, vägbeskrivning och information om natur, djurliv och historia längs banan.' where id = 34; -- Dressin på Österlen -  Fyledalen
update public.places set short_description = 'Uteritt på islandshästar nära Smedstorp', description = 'Österlens Tölthästar drivs av Alice Akkermann, utbildad ridinstruktör som arbetat som turledare sedan 2008. Huvudinriktningen är uteritter på islandshästar i det österlenska landskapet. Här bedrivs också avel med målet att få fram trygga islandshästar och den ovanliga rasen Aegidienberger. Hästar har varit Alices stora intresse sedan barndomen. Erbjudanden och nyheter läggs upp på Facebook och Instagram, så det är där man följer med i vad som händer under året och hittar lediga turer.' where id = 35; -- Österlens Tölthästar
update public.places set short_description = 'Museum om Simrishamn och byarnas historia', description = 'Österlens museum berättar Simrishamns och byarnas historia genom utställningar, stadsvisningar och program. Museet har öppet året runt, och det är fri entré till alla utställningar. Här finns också en museibutik med presenter, lokalt hantverk, böcker och historiska smycken. Museet är en InfoPoint där man kan få turistinformation och tips inför sitt besök på Österlen. Via museimagasinet Garvaren kan man söka i samlingarna, och museet har appar om utställningar, fornlämningar och stadsvandringar. Skolklasser kan boka besök.' where id = 37; -- Österlens Museum
update public.places set short_description = 'Bronsåldersröse med hällkista och bilder', description = 'Kiviksgraven, även kallad Bredarör eller Kungagraven, är Nordens bredaste stenröse. Det är ett röse från bronsåldern med en dekorerad hällkista, och den enda i Norden med hällbilder i kistan. Rekonstruktionen visar hur graven kan ha sett ut omkring 1400 före Kristus, men platsen har använts som begravningsplats från 5500 före Kristus till omkring 1050 efter Kristus. Under öppettid kan man gå in till hällkistan och se de 3400 år gamla bilderna. Graven ligger nära Kivik.' where id = 39; -- Kiviksgraven
update public.places set short_description = 'Livsmedelsbutik i Glemmingebro', description = 'Handlar''n i Glemmingebro är byns livsmedelsbutik, där man kan handla dagligvaror på vägen genom södra Österlen. Butiken har öppet alla dagar i veckan, med längre öppettider på vardagar och kortare på lördagar och söndagar. Glemmingebro ligger mellan Ystad och Simrishamn, nära Glimmingehus och flera kända besöksmål. Det gör butiken till ett praktiskt stopp för den som bor eller semestrar i trakten. Frågor om butiken kan skickas via kontaktformuläret på hemsidan eller ställas på telefon.' where id = 42; -- Handlar'n i Glemmingebro
update public.places set short_description = 'Hemtrevligt bed and breakfast fyllt med böcker', description = 'Bed and Books är ett gammaldags och hemtrevligt bed and breakfast i Glemmingebro. Här finns 15 rum med en till fem bäddar, och på varje rum finns böcker av författare som inspirerat rummet. I korridorerna finns böcker på svenska, engelska, tyska och franska. Gästerna delar på gästkök, två allrum med tv och spel samt en innergård med grillar. Frukostbuffén innehåller bland annat ägg från egna höns och bröd från närliggande Olof Viktors. Husdjur är välkomna mot en avgift.' where id = 43; -- Bed and Books på Österlen
update public.places set short_description = 'Järnvägshotell från 1902 i Vitaby', description = 'Hvitaby Järnvägshotell byggdes 1902 och ligger i Vitaby, mitt på Österlen. Hotellet kombinerar modernt boende i lugn miljö med gammaldags charm. Bad, golf och restauranger finns i närheten, och under sommaren kan man ta en tur med det gamla ångtåget. Det gör hotellet till en bra utgångspunkt för att upptäcka både kusten och inlandet. Här finns även café, galleri, kurser och möjlighet till konferens. Hotellet passar också för den som vill besöka Österlen under höst och vår.' where id = 47; -- Hvitaby Järnvägshotellet
update public.places set short_description = 'Klassiskt badhotell från 1913 vid stranden', description = 'Vitemölla Badhotell byggdes 1913 och är ett av få bevarade badhotell från tidigt 1900-tal på östkusten. Hotellet ligger precis vid stranden i fiskeläget Vitemölla, nära Kivik. Runt omkring finns natur som passar för långa promenader, till exempel Vitemölla strandbackar, Haväng och Stenshuvuds nationalpark. Hotellet har rum och lägenheter samt en restaurang. Hotellet har säsongsöppet, så det är bra att kolla deras hemsida inför bokning. Den som vill ha erbjudanden och nyheter kan prenumerera på hotellets nyhetsbrev.' where id = 48; -- Vitemölla badhotell
update public.places set short_description = 'Liten gårdskrog nära Kivik', description = 'Friden Gårdskrog är en liten krog på en gård nära Kivik, som drivs av Peter och Barbro. Krogen har öppet några dagar i veckan, främst från torsdag till söndag, och det är bäst att boka bord i förväg per telefon eller mejl. På gården finns också ett rum att hyra för den som vill stanna över natten. Krogen tar inte emot hundar, varken inne eller ute, och det finns ingen plats för husbilar på parkeringen. Friden passar för en lugn middag på landet.' where id = 50; -- Friden Gårdskrog
update public.places set short_description = 'Ferielägenheter på fyrlängad gård vid Kivik', description = 'Annagården är en varsamt bevarad fyrlängad skånegård strax utanför Södra Mellby, två kilometer från Kivik och havet. I de gamla längorna, där logen och stallet en gång låg, finns fyra personligt inredda och fullt utrustade ferielägenheter i olika storlekar. Varje lägenhet har egen ingång från innergården och en egen uteplats. Väluppfostrade hundar och katter är välkomna. Gården drivs av Gilla och Lasse, som har renoverat den efter att den legat i dvala i nästan tio år. Det finns även en lokal för fest och bröllop.' where id = 51; -- Annagården Österlen
update public.places set short_description = 'Familjeägt retrohotell från 60-talet i Kivik', description = 'Hanöbris är ett litet familjeägt retro- och designhotell i Kivik. Per och Carolina har återställt den unika 60-talsmiljön utan att göra avkall på bekvämligheten. Hotellet har 15 rum, och alla utom ett har egen balkong eller terrass. Samtliga rum har nybyggda duschar och toaletter, och det finns gratis wifi. Hotellet har säsongsöppet från påsk till äppelskörden, och tar även emot konferenser och bröllop. Ett steg in på Hanöbris beskrivs som ett steg sextio år tillbaka i tiden.' where id = 52; -- Hotell Hanöbris
update public.places set short_description = 'Bed and breakfast mitt i Kivik', description = 'Agda Lund är ett bed and breakfast i Kivik, med promenadavstånd till byns centrum, restauranger, hamnen och stränderna. Gården låg tidigare i en äppelodling, och därför bär alla elva rum namn efter äpplen som en gång odlades här, som Ingrid Marie, Alice och Greve Moltke. Från hotellet är det nära till cykel- och vandringsleder och till Stenshuvud, Knäbäckshusen och Haväng. Agda Lund tar också emot konferenser, med naturen och havet runt omkring. Rum bokas via deras hemsida.' where id = 53; -- Agda Lund B&B
update public.places set short_description = 'Fiskrestaurang vid havet i Simrishamn', description = 'Röken by Sonesson ligger i Simrishamn, tio meter från Östersjön, där Tommarpsån mynnar ut i havet. Från restaurangen ser man längs kusten mot Stenshuvud. Den inglasade matsalen har plats för 70 gäster, och lika många får plats på de uppvärmda uteplatserna under tak. Maten har inriktning på fisk, med rätter som stekt sill, lax, torsk och grillat, men också simrishamnsburgare och dagens lunch. Restaurangen ordnar provningar, tar emot stora och små sällskap och erbjuder catering till fester och bröllop.' where id = 55; -- Röken by Sonesson
update public.places set short_description = 'Bed and breakfast i centrala Simrishamn', description = 'Aurora Bed & Breakfast ligger i ett lugnt område mitt i Simrishamn och har öppet året runt. Här finns 13 personligt inredda rum med totalt 30 bäddar, fördelade på två våningar, och rummen har sköna sängar och platt-tv. Varje morgon serveras en frukostbuffé, och det finns även en trädgård. Gästerna kan parkera på gården, och det finns cykelställ för den som har med sig cykel. Huset är rökfritt inomhus och har trådlöst internet. Många gäster återkommer år efter år.' where id = 56; -- Aurora Bed & Breakfast
update public.places set short_description = 'Bageri och café i Kivik sedan 2000', description = 'Kiviks Café & Bageri drivs av Gun och dottern Martina sedan år 2000. Här bakas allt från grunden sju dagar i veckan, och caféet har öppet nästan hela året. I sortimentet finns surdegsbröd, stenugnsbakat bröd, bullar, kakor, bakelser och tårtor, och bageriet gör även bröllopstårtor. Sedan 2016 tillverkas här också spettekakor, och kunderna kan se när de görs. I caféet serveras frukostbuffé varje dag och lättare luncher, som pajer och soppor, och på torsdagar ärtsoppsbuffé.' where id = 59; -- Kiviks Café & Bageri
update public.places set short_description = 'Ekologisk besöksträdgård med gårdsbutik och kök', description = 'Mandelmanns Trädgårdar är en ekologisk besöksträdgård på gården Djupadal, som familjen Mandelmann har drivit sedan 1996. Gårdens marker är sextio hektar, och här finns dammar, växthus, djur, blommor och grönsaker. I Trädgårdsköket och gårdsbutiken serveras och säljs i princip bara sådant som kommer från gården. Det finns också ett litet fik i orangeriet och en webbutik. Trädgårdarna har säsongsöppet för besökare, och under vintern hålls bara butiken öppen vissa dagar, så kolla hemsidan innan besöket.' where id = 62; -- Mandelmanns Trädgårdar
update public.places set short_description = 'Litet hotell för vuxna nära Glimmingehus', description = 'Glivarpagården är ett litet, familjeägt hotell för vuxna, mitt på Österlen nära Glimmingehus. Hotellet har bara fyra rum och en semesterlägenhet, vilket gör det tyst och lugnt. Rummen är ljusa och rymliga med högt i tak, synliga takbjälkar och egna kaklade badrum, och alla har egen terrass med utsikt över fälten. Frukostbuffén består av hembakat bröd, marmelad med frukt och bär från trädgården och produkter från lokala producenter. Gästerna kan låna cyklar och få tips av Linus och Lotta.' where id = 64; -- Glivarpagården
commit;
